create or replace function public.admin_conversion_dashboard(range_days integer default 30) returns jsonb language plpgsql stable security definer set search_path = '' as $$ begin if auth.uid() is null or not private.has_role('admin'::public.user_role) then raise exception 'Admin access required'; end if; return jsonb_build_object('range_days', greatest(7, least(coalesce(range_days, 30), 90))); end; $$;
